{
  "name": "kafka_last",
  "description": "Live: the last n messages of a Kafka topic (newest first). Returns a preview plus `view`, a link to the full result as an interactive table (shown to the user inline). Mention the link.",
  "group": "kafka",
  "origin": "built-in",
  "execution": {
    "protocol": "dt.tool/v1",
    "transport": "in-process"
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "topic": {
        "type": "string",
        "description": "Topic name"
      },
      "env": {
        "type": "string",
        "enum": [
          "dev",
          "fixture"
        ],
        "default": "dev",
        "description": "Environment"
      },
      "n": {
        "type": "integer",
        "description": "Messages",
        "default": 5
      }
    },
    "required": [
      "topic"
    ]
  }
}
